// PRIMARY: beacon-chain/core/blocks/payload.go:verifyBlobCommitmentCount (lines 228-244)
func verifyBlobCommitmentCount(slot primitives.Slot, body interfaces.ReadOnlyBeaconBlockBody) error {
	if body.Version() < version.Deneb {
		return nil
	}
	kzgs, err := body.BlobKzgCommitments()
	if err != nil {
		return err
	}
	commitmentCount, maxBlobsPerBlock := len(kzgs), params.BeaconConfig().MaxBlobsPerBlock(slot)
	if commitmentCount > maxBlobsPerBlock {
		return fmt.Errorf("too many kzg commitments in block: actual count %d - max allowed %d", commitmentCount, maxBlobsPerBlock)
	}
	return nil
}
// NOTE: blob_gas_used and excess_blob_gas per EIP-4844 rules are validated by the execution engine. Prysm validates blob commitment count (beacon layer) but delegates gas accounting to the EL.

// PRIMARY: beacon-chain/core/electra/transition_no_verify_sig.go:ProcessOperations (lines 50-115)
func ProcessOperations(ctx context.Context, st state.BeaconState, block interfaces.ReadOnlyBeaconBlock) (state.BeaconState, error) {
	// ...
	// new in electra
	requests, err := bb.ExecutionRequests()
	if err != nil {
		return nil, errors.Wrap(err, "could not get execution requests")
	}
	st, err = ProcessDepositRequests(ctx, st, requests.Deposits)
	if err != nil {
		return nil, execReqErr{errors.Wrap(err, "could not process deposit requests")}
	}
	st, err = ProcessWithdrawalRequests(ctx, st, requests.Withdrawals)
	if err != nil {
		return nil, execReqErr{errors.Wrap(err, "could not process withdrawal requests")}
	}
	if err := ProcessConsolidationRequests(ctx, st, requests.Consolidations); err != nil {
		return nil, execReqErr{errors.Wrap(err, "could not process consolidation requests")}
	}
	return st, nil
}
// NOTE: Prysm processes EIP-7685 execution requests (deposits, withdrawals, consolidations) in ProcessOperations. The requests_hash itself is validated by the execution engine via Engine API newPayload; Prysm processes the contents.
